'use client';

import { createContext, useContext, useRef, type JSX, type ReactElement, type ReactNode } from 'react';
import {
  Button as RACButton,
  Collection,
  Header,
  ListBox,
  ListBoxItem,
  ListBoxSection,
  Popover,
  Select as RACSelect,
  SelectValue,
  Text,
  composeRenderProps,
  type ListBoxItemProps,
  type ListBoxSectionProps,
  type SelectProps as RACSelectProps,
  type ValidationResult,
} from 'react-aria-components';
import { IconCheck, IconChevronDown } from '@tabler/icons-react';
import { Description, FieldError, Label } from './text-field';
import styles from './select.module.css';

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(' ');

/**
 * Overlays portal to <body>, outside any ThemeScope. When the popover mounts, copy the trigger's scope
 * attributes (theme, scheme, density — and dir/lang if React Aria hasn't set them) onto it, so the popover
 * is a scope of its own and renders with the same tokens. Same approach as dialog.tsx.
 */
const SCOPE_ATTRS = ['data-strata-theme', 'data-strata-scheme', 'data-strata-density'] as const;
function mirrorScope(overlay: HTMLElement | null, source: Element | null): void {
  if (!overlay || !source || overlay.contains(source)) return;
  for (const name of SCOPE_ATTRS) {
    // Look each attribute up on its own: a single-tenant app themes :root and scopes only the scheme.
    const value = source.closest(`[${name}]`)?.getAttribute(name);
    if (value) overlay.setAttribute(name, value);
  }
  for (const name of ['dir', 'lang']) {
    const value = source.closest(`[${name}]`)?.getAttribute(name);
    if (value && !overlay.hasAttribute(name)) overlay.setAttribute(name, value);
  }
}

/** True while an item's content is being rendered inside the trigger (SelectValue), not the list. */
const InTriggerContext = createContext(false);

export interface SelectProps<T extends object> extends Omit<RACSelectProps<T>, 'children'> {
  /** Visible label. Pass `aria-label` instead only when a visible label is truly impossible. */
  label?: ReactNode;
  /** Help text under the trigger. */
  description?: ReactNode;
  /** Shown when the field is invalid. A string, or a function of RAC's validation result. */
  errorMessage?: string | ((validation: ValidationResult) => string);
  /** Items for dynamic collections; pair with a render function as `children`. */
  items?: Iterable<T>;
  /** `SelectItem` / `SelectSection` elements, or a function that renders one per item. */
  children: ReactNode | ((item: T) => ReactElement);
}

/**
 * A button that opens a list of options and shows the chosen one. Keyboard: Enter, Space or ↓ opens,
 * arrows move, typing jumps to a match, Enter selects, Escape closes.
 */
export function Select<T extends object>({
  label,
  description,
  errorMessage,
  items,
  children,
  className,
  ...props
}: SelectProps<T>): JSX.Element {
  const triggerRef = useRef<HTMLButtonElement>(null);
  return (
    <RACSelect<T> {...props} className={composeRenderProps(className, (c) => cx(styles.field, c))}>
      {label != null && <Label isRequired={props.isRequired}>{label}</Label>}
      <RACButton ref={triggerRef} className={styles.trigger}>
        <InTriggerContext.Provider value>
          <SelectValue className={styles.value} />
        </InTriggerContext.Provider>
        <span aria-hidden className={styles.chevronBox}>
          <IconChevronDown className={styles.chevron} />
        </span>
      </RACButton>
      {description != null && <Description>{description}</Description>}
      <FieldError>{errorMessage}</FieldError>
      <Popover offset={4} ref={(node) => mirrorScope(node, triggerRef.current)} className={styles.popover}>
        <ListBox<T> items={items} className={styles.listbox}>
          {children}
        </ListBox>
      </Popover>
    </RACSelect>
  );
}

export interface SelectItemProps<T extends object = object> extends Omit<ListBoxItemProps<T>, 'children'> {
  /** The option's label. A plain string also becomes its `textValue` for type-ahead. */
  children: ReactNode;
  /** A second, quieter line under the label. Not shown in the trigger. */
  description?: ReactNode;
  /** Leading icon (decorative). Shown in the list and in the trigger. */
  icon?: ReactNode;
}

function ItemContent({
  icon,
  description,
  isSelected,
  children,
}: {
  icon?: ReactNode;
  description?: ReactNode;
  isSelected: boolean;
  children: ReactNode;
}): JSX.Element {
  const inTrigger = useContext(InTriggerContext);
  if (inTrigger) {
    return (
      <>
        {icon != null && (
          <span aria-hidden className={styles.icon}>
            {icon}
          </span>
        )}
        <span className={styles.valueText}>{children}</span>
      </>
    );
  }
  return (
    <>
      {icon != null && (
        <span aria-hidden className={styles.icon}>
          {icon}
        </span>
      )}
      <span className={styles.itemText}>
        <Text slot="label" className={styles.itemLabel}>
          {children}
        </Text>
        {description != null && (
          <Text slot="description" className={styles.itemDescription}>
            {description}
          </Text>
        )}
      </span>
      <IconCheck aria-hidden className={styles.check} data-visible={isSelected || undefined} />
    </>
  );
}

/** One option in a Select. Give it an `id`; that is the key `selectedKey`/`onSelectionChange` use. */
export function SelectItem<T extends object = object>({
  children,
  description,
  icon,
  textValue,
  className,
  ...props
}: SelectItemProps<T>): JSX.Element {
  return (
    <ListBoxItem<T>
      {...props}
      textValue={textValue ?? (typeof children === 'string' ? children : undefined)}
      className={composeRenderProps(className, (c) => cx(styles.item, c))}
    >
      {({ isSelected }) => (
        <ItemContent icon={icon} description={description} isSelected={isSelected}>
          {children}
        </ItemContent>
      )}
    </ListBoxItem>
  );
}

export interface SelectSectionProps<T extends object = object> extends Omit<ListBoxSectionProps<T>, 'children'> {
  /** Section heading, e.g. "Europe". */
  title?: ReactNode;
  /** Items for a dynamic section; pair with a render function as `children`. */
  items?: Iterable<T>;
  children: ReactNode | ((item: T) => ReactElement);
}

/** Groups related options under a heading. */
export function SelectSection<T extends object = object>({
  title,
  items,
  children,
  className,
  ...props
}: SelectSectionProps<T>): JSX.Element {
  return (
    <ListBoxSection<T> {...props} className={cx(styles.section, className)}>
      {title != null && <Header className={styles.sectionHeader}>{title}</Header>}
      {items ? <Collection items={items}>{children}</Collection> : (children as ReactNode)}
    </ListBoxSection>
  );
}

/* Select. The trigger is drawn exactly like text-field's Input box (height, border, radius, states). */
.field {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: var(--strata-space-2);
  min-inline-size: 0;
}

.trigger {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: var(--strata-space-2);
  inline-size: 100%;
  min-inline-size: 0;
  block-size: var(--strata-control-height);
  margin: 0;
  padding-block: 0;
  /* The end side matches Combobox/DatePicker: a control-sized icon slot inset by one space step. */
  padding-inline: var(--strata-control-padding-inline) var(--strata-space-1);
  border: 1px solid var(--strata-color-border-strong);
  border-radius: var(--strata-radius-field);
  background-color: var(--strata-color-surface-default);
  color: var(--strata-color-text-default);
  font-family: inherit;
  font-size: var(--strata-font-size-md);
  line-height: var(--strata-line-height-normal);
  letter-spacing: inherit;
  text-align: start;
  cursor: default;
  outline: none;
}
.trigger[data-hovered] {
  border-color: var(--strata-color-text-subtle);
}
.trigger[data-focus-visible] {
  outline: 2px solid var(--strata-color-focus-ring);
  outline-offset: 2px;
}
.field[data-invalid] .trigger {
  border-color: var(--strata-color-feedback-danger-solid);
}
.trigger[data-disabled] {
  border-color: var(--strata-color-border-default);
  background-color: var(--strata-color-surface-sunken);
  color: var(--strata-color-text-disabled);
}

.value {
  display: flex;
  align-items: center;
  gap: var(--strata-space-2);
  flex: 1;
  min-inline-size: 0;
  overflow: hidden;
  white-space: nowrap;
}
.value[data-placeholder] {
  color: var(--strata-color-text-subtle);
}
.trigger[data-disabled] .value,
.trigger[data-disabled] .value[data-placeholder] {
  color: var(--strata-color-text-disabled);
}
.valueText {
  overflow: hidden;
  text-overflow: ellipsis;
}

.chevronBox {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  inline-size: calc(var(--strata-control-height) - var(--strata-space-2));
  color: var(--strata-color-text-subtle);
}
.chevron {
  inline-size: 1.15em;
  block-size: 1.15em;
  stroke-width: 2;
}
.field[data-open] .chevron {
  rotate: 180deg;
}
.trigger[data-disabled] .chevronBox {
  color: var(--strata-color-text-disabled);
}

/* ——— Popover + list (kept identical to combobox.module.css) ——— */
.popover {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  min-inline-size: var(--trigger-width);
  overflow: hidden;
  border: 1px solid var(--strata-color-border-default);
  border-radius: var(--strata-radius-container);
  background: var(--strata-color-surface-raised);
  color: var(--strata-color-text-default);
  box-shadow: var(--strata-shadow-overlay);
  font-family: var(--strata-font-body);
  font-size: var(--strata-font-size-md);
  line-height: var(--strata-line-height-normal);
  outline: none;
}

.listbox {
  box-sizing: border-box;
  flex: 1;
  min-block-size: 0;
  max-block-size: calc(var(--strata-space-16) * 5);
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: var(--strata-space-1);
  scroll-padding-block: var(--strata-space-1);
  outline: none;
}

.section + .section {
  margin-block-start: var(--strata-space-1);
  padding-block-start: var(--strata-space-1);
  border-block-start: 1px solid var(--strata-color-border-subtle);
}
.sectionHeader {
  padding-block: var(--strata-space-1);
  padding-inline: calc(var(--strata-control-padding-inline) - var(--strata-space-1));
  color: var(--strata-color-text-subtle);
  font-size: var(--strata-font-size-xs);
  font-weight: var(--strata-font-weight-medium);
  line-height: var(--strata-line-height-snug);
}

.item {
  --item-radius: min(var(--strata-radius-button), var(--strata-space-2));
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: var(--strata-space-2);
  min-block-size: calc(var(--strata-control-height) - var(--strata-space-2));
  padding-block: var(--strata-space-1);
  /* Listbox padding + this = control padding, so option text lines up with the trigger's text. */
  padding-inline: calc(var(--strata-control-padding-inline) - var(--strata-space-1)) var(--strata-space-2);
  border-radius: var(--item-radius);
  color: var(--strata-color-text-default);
  cursor: default;
  outline: none;
  forced-color-adjust: none;
}
.item[data-hovered],
.item[data-focused] {
  background: color-mix(in oklab, var(--strata-color-text-default) 6%, transparent);
}
.item[data-pressed] {
  background: color-mix(in oklab, var(--strata-color-text-default) 10%, transparent);
}
.item[data-focus-visible] {
  outline: 2px solid var(--strata-color-focus-ring);
  outline-offset: -2px;
}
.item[data-disabled] {
  color: var(--strata-color-text-disabled);
}
.item[data-disabled] .itemDescription,
.item[data-disabled] .icon {
  color: var(--strata-color-text-disabled);
}

.icon {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  color: var(--strata-color-text-subtle);
}
.icon > svg {
  inline-size: 1.15em;
  block-size: 1.15em;
}
.value .icon {
  color: inherit;
}

.itemText {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-inline-size: 0;
}
.itemLabel {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.item[data-selected] .itemLabel {
  font-weight: var(--strata-font-weight-medium);
}
.itemDescription {
  color: var(--strata-color-text-subtle);
  font-size: var(--strata-font-size-sm);
  line-height: var(--strata-line-height-snug);
}

.check {
  flex: none;
  inline-size: 1.15em;
  block-size: 1.15em;
  margin-inline-start: auto;
  color: var(--strata-color-text-default);
  stroke-width: 2;
  visibility: hidden;
}
.check[data-visible] {
  visibility: visible;
}

@media (prefers-reduced-motion: no-preference) {
  .trigger {
    transition: border-color var(--strata-motion-duration-fast) var(--strata-motion-easing);
  }
  .chevron {
    transition: rotate var(--strata-motion-duration-normal) var(--strata-motion-easing);
  }
  .popover[data-entering] {
    animation: popover-in var(--strata-motion-duration-fast) var(--strata-motion-easing);
  }
  .popover[data-exiting] {
    animation: popover-out var(--strata-motion-duration-fast) var(--strata-motion-easing) forwards;
  }
}
/* Slide from the side the popover opens towards (placement is physical, as is translate). */
.popover[data-placement='bottom'] {
  --popover-slide: 0 calc(var(--strata-space-1) * -1);
}
.popover[data-placement='top'] {
  --popover-slide: 0 var(--strata-space-1);
}
.popover[data-placement='left'] {
  --popover-slide: var(--strata-space-1) 0;
}
.popover[data-placement='right'] {
  --popover-slide: calc(var(--strata-space-1) * -1) 0;
}
@keyframes popover-in {
  from {
    opacity: 0;
    translate: var(--popover-slide, 0 0);
  }
}
@keyframes popover-out {
  to {
    opacity: 0;
    translate: var(--popover-slide, 0 0);
  }
}
